import{_ as n,o as a,c as p,a5 as t}from"./chunks/framework.Bt0SrEfo.js";const h=JSON.parse('{"title":"三、综合场景题","description":"","frontmatter":{},"headers":[],"relativePath":"面试/场景题/03-综合场景.md","filePath":"面试/场景题/03-综合场景.md","lastUpdated":1791733354000}'),e={name:"面试/场景题/03-综合场景.md"};function l(i,s,o,r,c,d){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="三、综合场景题" tabindex="-1">三、综合场景题 <a class="header-anchor" href="#三、综合场景题" aria-label="Permalink to &quot;三、综合场景题&quot;">​</a></h1><blockquote><p>摘自 <a href="./../场景面试题">场景面试题库</a></p></blockquote><h3 id="_17-如何做技术选型" tabindex="-1">17. 如何做技术选型？ <a class="header-anchor" href="#_17-如何做技术选型" aria-label="Permalink to &quot;17. 如何做技术选型？&quot;">​</a></h3><p><strong>场景</strong>：领导让你选一个状态管理库（Pinia / Zustand / Redux / MobX），你怎么选？</p><p><strong>答案要点</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 看场景</span></span>
<span class="line"><span>   - 简单状态（&lt; 5 个 slice）→ Zustand</span></span>
<span class="line"><span>   - 中等（5-20 个 slice）→ Pinia</span></span>
<span class="line"><span>   - 复杂（20+，时间旅行调试）→ Redux Toolkit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 看团队</span></span>
<span class="line"><span>   - Vue 项目 → Pinia（官方推荐）</span></span>
<span class="line"><span>   - React 项目 → Zustand / Redux</span></span>
<span class="line"><span>   - 老项目迁移 → 与现有 Redux 兼容</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 看需求</span></span>
<span class="line"><span>   - 需要时间旅行调试？→ Redux DevTools</span></span>
<span class="line"><span>   - 需要细粒度响应？→ MobX（基于 Proxy）</span></span>
<span class="line"><span>   - 需要 TypeScript 友好？→ Zustand（无 boilerplate）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 看趋势</span></span>
<span class="line"><span>   - 看 GitHub Star、npm 下载量、issue 响应速度</span></span>
<span class="line"><span>   - 看社区生态（中间件、devtools）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. POC 验证</span></span>
<span class="line"><span>   - 用真实业务场景写个 demo，2-3 天评估</span></span></code></pre></div><p><strong>追问</strong>：</p><ul><li>Pinia 和 Vuex 区别？→ Pinia 去掉 mutations，去掉 modules 嵌套，TS 友好</li><li>Redux Toolkit 解决了 Redux 什么问题？→ 简化样板代码，内置 immer</li><li>不用状态管理库可以吗？→ 小项目可以，跨组件共享状态多了就需要</li></ul><hr><h3 id="_18-ssr-csr-怎么选" tabindex="-1">18. SSR/CSR 怎么选？ <a class="header-anchor" href="#_18-ssr-csr-怎么选" aria-label="Permalink to &quot;18. SSR/CSR 怎么选？&quot;">​</a></h3><p><strong>场景</strong>：营销活动页（强 SEO）和后台系统（重交互）分别用什么方案？</p><p><strong>答案要点</strong>：</p><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th><th>理由</th></tr></thead><tbody><tr><td>营销页（SEO 重要）</td><td><strong>SSR</strong> (Next.js / Nuxt)</td><td>首屏直出 HTML，搜索引擎友好</td></tr><tr><td>后台系统（重交互）</td><td><strong>CSR</strong> (SPA)</td><td>不需要 SEO，首屏可慢，重交互性能好</td></tr><tr><td>内容站（博客）</td><td><strong>SSG</strong> (Next.js static / Hexo)</td><td>提前构建成静态文件，部署到 CDN</td></tr><tr><td>电商详情页</td><td><strong>ISR</strong> (Next.js)</td><td>兼顾性能和实时性（后台更新商品定时重新生成）</td></tr><tr><td>App 内嵌 H5</td><td><strong>CSR</strong></td><td>WebView 性能好 + 不需要 SEO</td></tr></tbody></table><p><strong>追问</strong>：</p><ul><li>SSR 有什么坑？→ 服务端渲染开销、Node 进程内存、缓存策略复杂</li><li>Next.js 14 默认什么？→ App Router 默认 SSR，但可以选 SSG/CSR</li><li>首屏白屏怎么解决？→ streaming + Suspense + skeleton</li></ul><hr><h3 id="_19-性能优化怎么量化" tabindex="-1">19. 性能优化怎么量化？ <a class="header-anchor" href="#_19-性能优化怎么量化" aria-label="Permalink to &quot;19. 性能优化怎么量化？&quot;">​</a></h3><p><strong>场景</strong>：PM 说&quot;页面太慢了&quot;，怎么定位和优化？</p><p><strong>答案要点</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 量化（先有数字）</span></span>
<span class="line"><span>   - Lighthouse / WebPageTest 跑分</span></span>
<span class="line"><span>   - 看 Web Vitals（LCP、INP、CLS）</span></span>
<span class="line"><span>   - 看真实用户监控（RUM）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 定位（看瓶颈在哪）</span></span>
<span class="line"><span>   - Chrome DevTools Performance</span></span>
<span class="line"><span>   - Long Task (&gt; 50ms 的任务)</span></span>
<span class="line"><span>   - 资源加载瀑布图</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 优化（按收益排）</span></span>
<span class="line"><span>   - 高 ROI：首屏渲染、图片懒加载、路由分割</span></span>
<span class="line"><span>   - 中 ROI：虚拟列表、Web Worker、长任务拆分</span></span>
<span class="line"><span>   - 低 ROI：JS 压缩、CSS 合并（默认做了）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 验证（跑分对比）</span></span>
<span class="line"><span>   - 优化前/后截图</span></span>
<span class="line"><span>   - 给 PM 看数字</span></span></code></pre></div><p><strong>追问</strong>：</p><ul><li>性能优化 ROI 怎么算？→ 用户停留时长 + 转化率</li><li>哪些优化是&quot;过度优化&quot;？→ 加载 1KB 图片压成 0.9KB（收益太小）</li><li>怎么避免优化回退？→ Lighthouse CI + 性能监控</li></ul><hr><h3 id="_20-老项目重构怎么推进" tabindex="-1">20. 老项目重构怎么推进？ <a class="header-anchor" href="#_20-老项目重构怎么推进" aria-label="Permalink to &quot;20. 老项目重构怎么推进？&quot;">​</a></h3><p><strong>场景</strong>：接手一个 5 年的 React 老项目（200+ 组件，无 TS，无测试），怎么重构？</p><p><strong>答案要点</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 先摸底（不要急着动代码）</span></span>
<span class="line"><span>   - 列出技术债务清单</span></span>
<span class="line"><span>   - 评估风险和收益</span></span>
<span class="line"><span>   - 和业务方对齐节奏</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 渐进式（不要 big bang）</span></span>
<span class="line"><span>   - 先加 TypeScript（jsconfig.json → 允许 .js）</span></span>
<span class="line"><span>   - 关键组件加单元测试（覆盖率 20% → 关键路径）</span></span>
<span class="line"><span>   - 拆分巨石组件（一个 5000 行文件 → 10 个 500 行）</span></span>
<span class="line"><span>   - 升级依赖（react 16 → 18，但分阶段）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 收益驱动（每个 PR 都有业务价值）</span></span>
<span class="line"><span>   - 重构期间性能提升 10% → 写进 PR 描述</span></span>
<span class="line"><span>   - TypeScript 覆盖率达 50% → 写入季度 OKR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 设立规则（避免越改越乱）</span></span>
<span class="line"><span>   - 新代码必须 TypeScript</span></span>
<span class="line"><span>   - PR 必须有单元测试</span></span>
<span class="line"><span>   - 引入 ESLint / Prettier / Husky</span></span></code></pre></div><p><strong>追问</strong>：</p><ul><li>怎么推动 TypeScript 迁移？→ 先 .d.ts 声明文件，再改 .ts</li><li>重构期间线上故障怎么办？→ Feature Flag + 灰度发布</li><li>团队抵触怎么办？→ 用业绩说话（重构后 bug 减少 X%）</li></ul><hr>`,30)])])}const g=n(e,[["render",l]]);export{h as __pageData,g as default};
